'use strict';
(() => {
const C=ClarityCore,S=ClarityStore,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const conditionNames={inline:'A · Inline underlines + warning',notice:'B · Warning only'};
const btn=(label,action,cl='',attrs='')=>`<button type="button" class="btn ${cl}" data-action="${action}" ${attrs}>${label}</button>`;
let modalFocus=null;
function notice(text){$('#toast').innerHTML=`<span>${esc(text)}</span>${btn('Dismiss','dismiss','compact')}`;$('#toast').hidden=false;}
function modal(title,content,actions){modalFocus=document.activeElement;$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2></div><div class="modal-content">${content}</div><div class="modal-actions">${actions}</div>`;$('#modal').showModal();$('#modal button')?.focus();}
function close(){if($('#modal').open)$('#modal').close();if(modalFocus?.isConnected)modalFocus.focus();}
function render(){const s=S.study();$('#research-app').innerHTML=`<main id="main" class="research-shell" tabindex="-1"><header class="research-header"><div><a class="brand" href="index.html"><span class="brand-mark">C</span><span class="brand-word">Clarity</span></a><h1>Researcher console</h1><p>Prepare consistent tasks. Observe without leading. Export locally.</p></div><a class="btn" href="index.html" target="clarity-participant">Open participant view ↗</a></header><div class="info-banner">Keep this console on the researcher’s screen. Read or print the neutral task instructions separately. The participant view does not display conditions, hypotheses, or success criteria.</div>${S.storageProblem?'<div class="info-banner warning">Local storage is unavailable. Cross-tab study control and persistent recording cannot be relied on. Enable storage and reload before collecting data.</div>':''}<div class="research-grid"><section class="research-card"><h2>1. Session setup</h2><p>Recording is off until consent is confirmed and the participant begins a prepared task. Use fictional information only.</p><form id="study-setup"><div class="study-controls"><label class="field">Anonymous participant ID<input id="participant-id" value="${esc(s.participant)}" pattern="P[0-9]{2,4}" maxlength="5" required placeholder="P01" ${s.active?'disabled':''}><small>Use P01–P9999. Never enter a name.</small></label><label class="field">Evaluation mode<select id="study-mode" ${s.active?'disabled':''}><option value="thinkaloud" ${s.mode==='thinkaloud'?'selected':''}>Think-aloud usability study</option><option value="timed" ${s.mode==='timed'?'selected':''}>Timed experiment</option></select><small>Analyse these modes separately.</small></label></div><label class="check-row"><input type="checkbox" id="consent" ${s.consent?'checked':''} ${s.active?'disabled':''}>Consent obtained for local anonymous interaction logging</label><div class="research-actions"><button class="btn primary" type="submit" ${s.active?'disabled':''}>Save session setup</button>${btn('Stop recording','stop-recording','',!s.consent?'disabled':'')}</div><p id="setup-status" class="status-line">${s.consent?'Consent recorded for '+esc(s.participant)+'.':'No consent recorded. Interaction recording is off.'}</p></form></section><section class="research-card"><h2>2. Prepare a task</h2><p>Each task starts from the same fictional data. Preparing replaces participant drafts, conversations, profile changes and preferences; it keeps study records.</p><label class="field">Condition<select id="condition" ${s.active?'disabled':''}>${Object.entries(conditionNames).map(([v,l])=>`<option value="${v}" ${s.condition===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Scenario<select id="scenario" ${s.active?'disabled':''}>${Object.entries(C.scenarios).map(([v,x])=>`<option value="${v}" ${s.scenario===v?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><div id="scenario-details"></div><div class="research-actions">${btn('Prepare task','prepare','primary',s.active||!s.consent?'disabled':'')}${btn('Print task sheet','print-task')}</div><p class="status-line">The clock starts when the participant selects Begin task. For the masking comparison, it stops at their first send.</p></section><section class="research-card"><h2>3. Observe the session</h2><div id="live-session"></div><div class="research-actions">${btn('End current task','end-task','',s.active?.startedAt?'':'disabled')}${btn('Cancel prepared task','cancel-task','',s.active&&!s.active.startedAt?'':'disabled')}</div><div class="subtle-divider"></div><p><strong>Think-aloud:</strong> “Please keep telling me what you are thinking.” Avoid suggesting a control or explaining a warning during the task. Record assistance explicitly.</p><p><strong>Timed experiment:</strong> no concurrent think-aloud. Use retrospective questions after the timer stops; avoid coaching.</p></section><section class="research-card"><h2>4. Export & reset</h2><p>Exports contain participant IDs, conditions, task times, outcomes, assistance, and interaction events. They exclude raw prompt text, flagged values, chat content, and profile content.</p><div class="research-actions">${btn('Export JSON','export-json','primary')}${btn('Export task CSV','export-csv')}${btn('Export event CSV','export-events')}</div><p id="record-count" class="status-line"></p><div class="subtle-divider"></div><p>Reset the participant workspace between sessions. Clear research records only after saving any required export.</p><div class="research-actions">${btn('Reset participant workspace','reset-workspace','',s.active?'disabled':'')}${btn('Clear all local study data','clear-all','text-danger')}</div><p class="status-line">Resetting cannot remove files already downloaded. Clearing all data also restores participant data to the initial fictional examples.</p></section><section class="research-card wide"><h2>Participant-by-task records</h2><p>Mark each outcome and the assistance given. Automated observations check simple content rules only; a researcher must confirm task quality and explanations.</p><div id="trial-records"></div></section><section class="research-card wide"><h2>Comparison & study guide</h2><p><strong>Proposed hypothesis:</strong> inline underlines reduce the time to send a useful request with the sample credential removed, compared with the same nearby warning alone. Treat this as untested.</p><div class="table-scroll"><table class="research-table"><thead><tr><th>Element</th><th>Plan</th></tr></thead><tbody><tr><td>Independent variable</td><td>Inline underlines present vs absent. Both conditions retain the same warning and review panel.</td></tr><tr><td>Primary measure</td><td>Time from Begin task to first send, for correctly completed masking tasks. Also report failures and unreviewed sends.</td></tr><tr><td>Controls</td><td>Same patterns, suggestions, scripts, buttons, notice mode, starting state and device. Match the two fictional credential tasks.</td></tr><tr><td>Design</td><td>Within-participant comparison with balanced condition/task order. Plan for at least 10 participants; 12 evenly fills the four sequence groups below.</td></tr><tr><td>Counterbalancing</td><td>Rotate: A/maskA → B/maskB; B/maskB → A/maskA; A/maskB → B/maskA; B/maskA → A/maskB.</td></tr><tr><td>Confounds</td><td>Learning from the first condition; individual familiarity with privacy tools and technical error messages. Balance order and standardise a practice task.</td></tr><tr><td>Analysis</td><td>Preselect a paired analysis and justify its assumptions. Report completion rates alongside times; do not treat failed or assisted tasks as ordinary successful timings.</td></tr></tbody></table></div><div class="research-nav"><a href="study-guide.html" target="_blank" rel="noopener">Full testing guide, consent & task sheets ↗</a><a href="design-notes.html" target="_blank" rel="noopener">Research traceability & design trade-offs ↗</a></div></section></div></main>`;renderScenario();updateLive();renderTrials();}
function renderScenario(){const id=$('#scenario')?.value||S.study().scenario,x=C.scenarios[id];$('#scenario-details').innerHTML=`<div class="eyebrow">Neutral participant instruction</div><div class="task-instruction">${esc(x.instruction)}</div><div class="task-success"><strong>Researcher success criterion</strong><br>${esc(x.success)}</div>`;}
function updateLive(){const s=S.study(),a=s.active;if(!$('#live-session'))return;$('#live-session').innerHTML=a?`<div class="research-status"><span class="dot"></span>${a.startedAt?'Recording · task in progress':'Prepared · awaiting participant start'}</div><div class="timer">${a.startedAt?((Date.now()-a.startedAt)/1000).toFixed(1):'0.0'}<small> s</small></div><p class="status-line">${esc(a.participantId)} · ${conditionNames[a.condition]}<br>${esc(C.scenarios[a.scenario].name)} · ${a.mode==='timed'?'Timed experiment':'Think-aloud'}</p>`:`<p class="research-status">No active task. Prepare a scenario to begin.</p><div class="timer">—</div>`;$('#record-count').textContent=`${s.trials.length} completed task record${s.trials.length===1?'':'s'} · ${s.events.length} events stored locally.`;}
function renderTrials(){const s=S.study();$('#trial-records').innerHTML=s.trials.length?`<div class="table-scroll"><table class="research-table"><thead><tr><th>ID / mode</th><th>Condition / task</th><th>Time</th><th>Rule check</th><th>Observed outcome</th><th>Assistance</th></tr></thead><tbody>${s.trials.map(t=>`<tr><td>${esc(t.participantId)}<br><small>${t.mode}</small></td><td>${t.condition==='inline'?'A':'B'} · ${esc(C.scenarios[t.scenario]?.name||t.scenario)}</td><td>${(t.durationMs/1000).toFixed(2)} s</td><td>${t.observedSuccess===true?'Pass':t.observedSuccess===false?'Not met':'Manual review'}</td><td><label class="sr-only" for="outcome-${t.id}">Outcome for ${esc(t.participantId)} ${esc(t.scenario)}</label><select id="outcome-${t.id}" data-trial="${t.id}" data-field="outcome">${['unrated','success','partial','failed','abandoned'].map(o=>`<option ${t.outcome===o?'selected':''}>${o}</option>`).join('')}</select></td><td><label class="sr-only" for="assistance-${t.id}">Assistance for ${esc(t.participantId)} ${esc(t.scenario)}</label><select id="assistance-${t.id}" data-trial="${t.id}" data-field="assistance">${['unrecorded','none','neutral reminder','clarification','guided assistance'].map(o=>`<option ${t.assistance===o?'selected':''}>${o}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><h3>No task records yet</h3><p>Finished tasks appear here. No results are prefilled.</p></div>';}
function prepare(){const s=S.study();if(!s.consent||s.active)return;const scenario=$('#scenario').value,condition=$('#condition').value;const x=C.scenarios[scenario];modal('Prepare a consistent starting state?',`<p>This will replace the participant workspace with fictional baseline data for “${esc(x.name)}.” Study records stay intact.</p><p>Give the participant the task sheet before they select Begin task. Keep this console hidden from their view.</p>`,btn('Cancel','close')+btn('Prepare task','confirm-prepare','primary',`data-scenario="${scenario}" data-condition="${condition}"`));}
function confirmPrepare(scenario,condition){const s=S.study();if(s.active)return;let state=C.seed();state.chats[0].draft=C.scenarios[scenario].prompt;state.prefs.warningMode='notice';if(scenario==='preferences'){state.prefs.reuseMode='auto';state.items.forEach(x=>{if(x.group!=='inferences')x.reuse='default';});}if(scenario==='followup'){state.chats[0].title='Debugging a request';state.chats[0].messages=[{role:'user',text:'Why does my request return 401? API_KEY = [API key].'},{role:'assistant',text:'Check that the Authorization header is present and that the credential has the right permissions. Would a small example help?'}];}s.scenario=scenario;s.condition=condition;s.active={id:S.uid(),participantId:s.participant,condition,scenario,mode:s.mode,startedAt:null};S.saveState(state);S.saveStudy(s);close();render();notice('Task prepared. Open the participant view and let them select Begin task.');}
function download(name,type,content){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);notice('Export created. Downloaded files remain outside the prototype.');}
function csv(rows,columns){return columns.join(',')+'\r\n'+rows.map(r=>columns.map(k=>{let v=String(r[k]??'');if(/^[=+@-]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
function exportData(type){const s=S.study();if(s.active){notice('Finish or cancel the active task before exporting a complete dataset.');return;}if(type==='json')download('clarity-study.json','application/json',JSON.stringify({schemaVersion:1,prototype:'Clarity',conditions:conditionNames,rawPromptTextIncluded:false,timingDefinition:'Begin task to first send for chat tasks; otherwise explicit finish. Think-aloud and timed modes must be analysed separately.',trials:s.trials,events:s.events},null,2));else if(type==='csv')download('clarity-tasks.csv','text/csv;charset=utf-8',csv(s.trials,['id','participantId','condition','scenario','mode','durationMs','observedSuccess','outcome','assistance','stopReason']));else download('clarity-events.csv','text/csv;charset=utf-8',csv(s.events,['trialId','participantId','condition','scenario','mode','elapsedMs','event','category','screen','count','action','source','success','retainedCount','unreviewedCount','reason','choice']));}
document.addEventListener('submit',e=>{if(e.target.id!=='study-setup')return;e.preventDefault();const s=S.study();if(s.active)return;const id=$('#participant-id').value;if(!/^P\d{2,4}$/.test(id)){notice('Use an anonymous code such as P01.');return;}s.participant=id;s.mode=$('#study-mode').value;s.consent=$('#consent').checked;S.saveStudy(s);render();notice(s.consent?'Session saved. Prepare a task to continue.':'Session saved. Recording is off.');});
document.addEventListener('change',e=>{if(e.target.id==='scenario')renderScenario();if(e.target.dataset.trial){const s=S.study(),t=s.trials.find(x=>x.id===e.target.dataset.trial);if(t){t[e.target.dataset.field]=e.target.value;S.saveStudy(s);notice('Task record updated locally.');}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case 'dismiss':$('#toast').hidden=true;break;case 'close':close();break;case 'prepare':prepare();break;case 'confirm-prepare':confirmPrepare(b.dataset.scenario,b.dataset.condition);break;case 'end-task':S.finish(null,'researcher_ended');render();notice('Task ended. Record the outcome and assistance.');break;case 'cancel-task':{const s=S.study();if(s.active&&!s.active.startedAt){s.active=null;S.saveStudy(s);render();notice('Unstarted task cancelled. No task record was created.');}break;}case 'stop-recording':{S.finish(null,'recording_stopped');const s=S.study();s.active=null;s.consent=false;S.saveStudy(s);render();notice('Recording stopped. Existing local records remain until cleared.');break;}case 'export-json':exportData('json');break;case 'export-csv':exportData('csv');break;case 'export-events':exportData('events');break;case 'reset-workspace':modal('Reset the participant workspace?', '<p>Replace all local chats, drafts, profile items, removed items and preferences with the initial fictional examples. This cannot be undone. Anonymous research records remain.</p>',btn('Cancel','close')+btn('Reset workspace','confirm-reset','danger'));break;case 'confirm-reset':S.saveState(C.seed());close();render();notice('Participant workspace reset. Research records kept.');break;case 'clear-all':modal('Clear all local study data?', '<p>This deletes all anonymous study records and replaces the participant workspace with fictional defaults. It cannot be undone. Already downloaded exports are unaffected.</p>',btn('Cancel','close')+btn('Clear all local data','confirm-clear','danger'));break;case 'confirm-clear':S.saveState(C.seed());S.saveStudy(S.emptyStudy());close();render();notice('Local research records cleared; fictional participant baseline restored.');break;case 'print-task':{const x=C.scenarios[$('#scenario').value];const w=window.open('','_blank');if(!w){notice('Allow a new window to print the task sheet.');return;}w.document.write(`<!doctype html><html lang="en"><meta charset="utf-8"><title>Clarity task sheet</title><body style="font:18px/1.7 Arial;padding:50px;max-width:800px;margin:auto"><h1>Task information sheet</h1><p>Use only the fictional information provided. You may stop or skip the task at any time.</p><p>${esc(x.instruction)}</p><p>When you are ready, select Begin task in the participant view.</p><p>${S.study().mode==='thinkaloud'?'Please say what you are thinking, what you expect, and anything you find confusing.':'Work at your normal pace without thinking aloud. We will ask about your experience afterwards.'}</p></body></html>`);w.document.close();w.print();break;}}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();close();});
window.addEventListener('storage',e=>{if(e.key===S.STUDY){const had=!!$('#live-session .dot'),has=!!S.study().active;if(had!==has)render();else{updateLive();renderTrials();const a=S.study().active;$('[data-action="end-task"]').disabled=!a?.startedAt;$('[data-action="cancel-task"]').disabled=!a||!!a.startedAt;}}});
setInterval(updateLive,250);render();
})();
